            buffer_size += snp_res;
            snp_res = snprintf(buffer, buffer_length - buffer_size, "f_ctrl_measure: 0x%x\n", reg_data->page_data.ppll_28nm.pll_status[i].f_ctrl_measure);
            VALIDATE_ROLLBACK(snp_res, buffer_length, buffer_size);
