            buffer_size += snp_res;
            snp_res = snprintf(buffer, buffer_length - buffer_size, "analog_var: 0x%x\n", reg_data->page_data.ppll_28nm.pll_status[i].analog_var);
            VALIDATE_ROLLBACK(snp_res, buffer_length, buffer_size);
            buffer += snp_res;
